/**
 * 管理类：用多态数组管理所有人员。
 */
class PersonManager {
    /** 多态数组：元素类型是父类 Person，实际存放各类子类对象 */
    private Person[] persons;
    /** 当前已存放的人数 */
    private int count;

    /**
     * 构造方法
     * @param capacity 数组容量
     */
    public PersonManager(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("容量必须大于 0");
        }
        this.persons = new Person[capacity];
        this.count = 0;
    }

    /**
     * 添加人员
     * @param person 人员对象（可以是 Student 或 Teacher）
     * @return 添加成功返回 true，数组已满返回 false
     */
    public boolean add(Person person) {
        if (person == null) {
            System.out.println("添加失败：对象为 null");
            return false;
        }
        if (count >= persons.length) {
            System.out.println("添加失败：数组已满，无法添加 " + person.getName());
            return false;
        }
        persons[count] = person;
        count++;
        System.out.println("添加成功：" + person.getName() + "（" + person.getType() + "）");
        return true;
    }

    /** 展示所有人员信息：多态调用 showInfo() */
    public void showAll() {
        System.out.println("===== 全部人员信息（共 " + count + " 人）=====");
        for (int i = 0; i < count; i++) {
            // 多态：运行时才确定调用 Student 还是 Teacher 的 showInfo()
            System.out.println((i + 1) + ". " + persons[i].showInfo());
        }
    }

    /**
     * 按姓名查找人员
     * @param name 姓名
     * @return 找到返回该人员，未找到返回 null
     */
    public Person findByName(String name) {
        for (int i = 0; i < count; i++) {
            if (persons[i].getName().equals(name)) {
                return persons[i];
            }
        }
        return null;
    }

    /** 统计各类人员数量：使用 instanceof 分类统计 */
    public void statistics() {
        int studentCount = 0;
        int teacherCount = 0;
        double totalScore = 0;

        for (int i = 0; i < count; i++) {
            if (persons[i] instanceof Student) {
                Student s = (Student) persons[i];      // 向下转型
                studentCount++;
                totalScore += s.getScore();
            } else if (persons[i] instanceof Teacher) {
                teacherCount++;
            }
        }

        System.out.println("===== 统计结果 =====");
        System.out.println("学生人数：" + studentCount);
        System.out.println("教师人数：" + teacherCount);
        if (studentCount > 0) {
            System.out.printf("学生平均成绩：%.2f%n", totalScore / studentCount);
        } else {
            System.out.println("学生平均成绩：暂无学生数据");
        }
    }

    /** 计算所有教师的年收入总和 */
    public double totalTeacherIncome() {
        double total = 0;
        for (int i = 0; i < count; i++) {
            if (persons[i] instanceof Teacher) {
                total += ((Teacher) persons[i]).annualIncome();
            }
        }
        return total;
    }
}
