#### 7.47.2 综合案例二：图形面积计算系统

**（1）需求描述**：定义一个图形接口 `Shape`，包含计算面积、周长与获取名称的方法，并提供默认方法与静态方法；实现矩形、圆形、三角形三个实现类；编写工具类，用多态参数计算任意图形的面积，并支持按面积排序。

**（2）完整代码**：

```java
import java.util.Arrays;
import java.util.Comparator;

/**
 * 图形接口：定义所有二维图形必须具备的能力。
 */
interface Shape {
    /**
     * 计算面积
     * @return 面积
     */
    double area();

    /**
     * 计算周长
     * @return 周长
     */
    double perimeter();

    /**
     * 获取图形名称
     * @return 名称
     */
    String getName();

    /**
     * 默认方法（JDK 8）：判断是否为"大面积"图形
     * @return 面积大于等于 100 返回 true
     */
    default boolean isLarge() {
        return area() >= 100;
    }

    /**
     * 静态方法（JDK 8）：比较两个图形的面积大小
     * @param s1 图形一
     * @param s2 图形二
     * @return s1 面积大返回正数，相等返回 0，否则返回负数
     */
    static int compareByArea(Shape s1, Shape s2) {
        return Double.compare(s1.area(), s2.area());
    }
}
```

```java
/**
 * 矩形实现类。
 */
class Rectangle implements Shape {
    private double width;
    private double height;

    public Rectangle(double width, double height) {
        if (width <= 0 || height <= 0) {
            throw new IllegalArgumentException("边长必须大于 0");
        }
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() {
        return width * height;
    }

    @Override
    public double perimeter() {
        return 2 * (width + height);
    }

    @Override
    public String getName() {
        return "矩形(" + width + "×" + height + ")";
    }
}
```

```java
/**
 * 圆形实现类。
 */
class Circle implements Shape {
    private double radius;

    public Circle(double radius) {
        if (radius <= 0) {
            throw new IllegalArgumentException("半径必须大于 0");
        }
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }

    @Override
    public double perimeter() {
        return 2 * Math.PI * radius;
    }

    @Override
    public String getName() {
        return "圆形(半径 " + radius + ")";
    }
}
```

```java
/**
 * 三角形实现类：使用海伦公式计算面积。
 */
class Triangle implements Shape {
    private double a;
    private double b;
    private double c;

    public Triangle(double a, double b, double c) {
        if (a <= 0 || b <= 0 || c <= 0) {
            throw new IllegalArgumentException("边长必须大于 0");
        }
        // 三角形不等式：任意两边之和必须大于第三边
        if (a + b <= c || a + c <= b || b + c <= a) {
            throw new IllegalArgumentException("三条边无法构成三角形");
        }
        this.a = a;
        this.b = b;
        this.c = c;
    }

    @Override
    public double area() {
        double p = (a + b + c) / 2;            // 半周长
        return Math.sqrt(p * (p - a) * (p - b) * (p - c));
    }

    @Override
    public double perimeter() {
        return a + b + c;
    }

    @Override
    public String getName() {
        return "三角形(" + a + "," + b + "," + c + ")";
    }
}
```

```java
/**
 * 图形工具类：所有方法都是静态方法，通过类名直接调用。
 */
class ShapeUtil {
    /**
     * 计算任意图形的面积（多态参数）
     * @param shape 图形对象
     * @return 面积
     */
    public static double areaOf(Shape shape) {
        return shape.area();
    }

    /**
     * 计算一组图形的总面积
     * @param shapes 图形数组（多态数组）
     * @return 总面积
     */
    public static double totalArea(Shape[] shapes) {
        double total = 0;
        for (Shape shape : shapes) {
            total += shape.area();
        }
        return total;
    }

    /**
     * 打印图形详细信息
     * @param shape 图形对象
     */
    public static void printDetail(Shape shape) {
        System.out.printf("%s：面积=%.4f，周长=%.4f，是否大面积=%s%n",
                shape.getName(), shape.area(), shape.perimeter(), shape.isLarge());
    }

    /** 私有构造方法：工具类禁止实例化 */
    private ShapeUtil() {
        throw new AssertionError("工具类禁止实例化");
    }
}
