                return Shape.compareByArea(o1, o2);
            }
        });

        System.out.println("===== 按面积升序排序后 =====");
        for (Shape shape : shapes) {
            System.out.printf("%s -> %.4f%n", shape.getName(), shape.area());
        }
    }
}
