#### 7.47.3 综合案例三：员工工资计算系统

**（1）需求描述**：公司有三类员工——**正式员工**（固定月薪）、**小时工**（按时薪计算，超 160 小时部分 1.5 倍）、**销售人员**（底薪 + 销售额提成）。要求用抽象类定义公共部分，用多态数组计算所有人的工资总额，并按工资降序输出。

**（2）完整代码**：

```java
import java.util.Arrays;

/**
 * 抽象类：员工。
 * 封装公共属性，定义公共方法，声明抽象方法计算工资。
 */
abstract class Employee implements Comparable<Employee> {
    private String id;
    private String name;

    public Employee(String id, String name) {
        this.id = id;
        this.name = name;
    }

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    /**
     * 抽象方法：计算工资，由各子类实现不同的计算规则
     * @return 本月工资
     */
    public abstract double calculateSalary();

    /**
     * 抽象方法：获取员工类型
     * @return 类型名称
     */
    public abstract String getType();

    /**
     * 实现 Comparable 接口：按工资降序排序
     * @param other 另一个员工
     * @return 比较结果
     */
    @Override
    public int compareTo(Employee other) {
        return Double.compare(other.calculateSalary(), this.calculateSalary());
    }

    @Override
    public String toString() {
        return String.format("%s[%s, %s] 工资：%.2f 元",
                getType(), id, name, calculateSalary());
    }
}
```

```java
/**
 * 子类：正式员工，固定月薪。
 */
class FullTimeEmployee extends Employee {
    private double monthlySalary;

    public FullTimeEmployee(String id, String name, double monthlySalary) {
        super(id, name);
        if (monthlySalary < 0) {
            throw new IllegalArgumentException("月薪不能为负数");
        }
        this.monthlySalary = monthlySalary;
    }

    @Override
    public double calculateSalary() {
        return monthlySalary;
    }

    @Override
    public String getType() {
        return "正式员工";
    }
}
```

```java
/**
 * 子类：小时工，超出 160 小时的部分按 1.5 倍计算。
 */
class PartTimeEmployee extends Employee {
    private int hours;
    private double hourlyRate;

    public PartTimeEmployee(String id, String name, int hours, double hourlyRate) {
        super(id, name);
        this.hours = hours;
        this.hourlyRate = hourlyRate;
    }

    @Override
    public double calculateSalary() {
        if (hours <= 160) {
            return hours * hourlyRate;
        }
        return 160 * hourlyRate + (hours - 160) * hourlyRate * 1.5;
    }

    @Override
    public String getType() {
        return "小时工";
    }
}
```

```java
/**
 * 子类：销售人员，底薪 + 销售额提成。
 */
class SalesEmployee extends Employee {
    private double baseSalary;
    private double salesAmount;
    private double commissionRate;

    public SalesEmployee(String id, String name, double baseSalary,
                         double salesAmount, double commissionRate) {
        super(id, name);
        this.baseSalary = baseSalary;
        this.salesAmount = salesAmount;
        this.commissionRate = commissionRate;
    }

    @Override
    public double calculateSalary() {
        return baseSalary + salesAmount * commissionRate;
    }

    @Override
    public String getType() {
        return "销售人员";
    }
}
```

```java
