2. 定义三个实现类：`Alipay`、`WechatPay`、`CreditCard`，分别返回不同的渠道名称；
3. 定义一个 `PaymentService` 类，含方法 `void process(Payable payable, double amount)`，输出支付过程；
4. 在 `main` 中分别用三种支付方式支付，并统计成功支付的次数。

**答案**：

```java
/**
 * 支付接口：定义支付规范。
 */
interface Payable {
    /**
     * 执行支付
     * @param amount 金额
     * @return 支付成功返回 true
     */
    boolean pay(double amount);

    /**
     * 获取渠道名称（默认方法，JDK 8）
     * @return 渠道名称
     */
    default String getChannelName() {
        return "未知渠道";
    }
}

/**
 * 支付宝支付。
 */
class Alipay implements Payable {
    @Override
    public boolean pay(double amount) {
        if (amount <= 0) {
            System.out.println("支付宝：金额非法");
            return false;
        }
        System.out.println("支付宝：成功支付 " + amount + " 元");
        return true;
    }

    @Override
    public String getChannelName() {
        return "支付宝";
    }
}

/**
 * 微信支付。
 */
class WechatPay implements Payable {
    @Override
    public boolean pay(double amount) {
        if (amount <= 0) {
            System.out.println("微信支付：金额非法");
            return false;
        }
        System.out.println("微信支付：成功支付 " + amount + " 元");
        return true;
    }

    @Override
    public String getChannelName() {
        return "微信支付";
    }
}

/**
 * 信用卡支付：单笔限额 5000 元。
 */
class CreditCard implements Payable {
    /** 单笔限额 */
    private static final double LIMIT = 5000.0;

    @Override
    public boolean pay(double amount) {
        if (amount <= 0) {
            System.out.println("信用卡：金额非法");
            return false;
        }
        if (amount > LIMIT) {
            System.out.println("信用卡：单笔限额 " + LIMIT + " 元，支付失败");
            return false;
        }
        System.out.println("信用卡：成功支付 " + amount + " 元");
        return true;
    }

    @Override
    public String getChannelName() {
        return "信用卡";
    }
}

/**
 * 支付服务：只依赖接口，不依赖具体实现。
 */
class PaymentService {
    /** 成功支付次数（静态计数器） */
    private static int successCount = 0;

    /**
     * 处理支付
     * @param payable 支付渠道（多态参数）
     * @param amount 金额
     */
    public void process(Payable payable, double amount) {
        System.out.print("【" + payable.getChannelName() + "】");
        if (payable.pay(amount)) {
            successCount++;
        }
    }

    public static int getSuccessCount() {
        return successCount;
    }
}
```

```java
/**
 * 测试类：支付系统。
 */
public class PaymentTest {
    public static void main(String[] args) {
        PaymentService service = new PaymentService();

        service.process(new Alipay(), 199.0);
        service.process(new WechatPay(), 88.5);
        service.process(new CreditCard(), 6000.0);      // 超过限额，失败
        service.process(new CreditCard(), 3000.0);
        service.process(new Alipay(), -50);             // 金额非法，失败

        System.out.println("成功支付次数：" + PaymentService.getSuccessCount());
    }
}
```

